function supplementalTerm(section, concepts, index) {
  const name = concepts[index];
  const tag = section.tags[index % section.tags.length];
  const prev = concepts[index - 1];
  const next = concepts[index + 1];
  const related = [prev, next].filter(Boolean);
  return term(
    name,
    tag,
    `${name}是${section.title}中的重要名词，常用于${section.focus}。理解它有助于把该领域的设计、实现、排障和优化串起来；在真实工程里通常还要同时考虑成本、可靠性、安全边界和长期可维护性。`,
    `${name}像${section.metaphor}里的一个关键部件，单独看只是一个零件，放进完整系统后才会显出它和上下游之间的配合关系。`,
    related
  );
}

