roadmapBoardExpansions.forEach((section) => {
  const target = dictionary.find((item) => item.id === section.target);
  if (!target) return;
  const existing = new Set(target.terms.map((item) => item.name));
  const names = section.concepts.filter((name) => !existing.has(name));
  target.terms.push(...names.map((_, index) => supplementalTerm(section, names, index)));
});

