    term("可达性", "对象关系", "可达性描述某个对象能否从根对象、变量或入口沿引用链访问到，常用于垃圾回收和图算法。", "可达性像城市路网里能不能从火车站走到某个小区，走不到的地方就像失联对象。", ["引用", "垃圾回收"]),
    term("确定性算法", "算法性质", "确定性算法在相同输入和相同初始状态下总会产生相同结果，便于测试、复现和推理。", "它像按固定菜谱做饭，只要食材和步骤相同，味道应当稳定。", ["确定性", "非确定性"]),
    term("随机化算法", "算法策略", "随机化算法在执行中使用随机选择，以换取更简单的实现、平均性能或更好的抗最坏情况能力。", "它像在拥堵城市里随机选几条备选路，有时比所有人都挤主路更聪明。", ["概率", "算法"])
