Object.entries(bookDrivenExpansionTerms).forEach(([sectionId, items]) => {
  const target = dictionary.find((section) => section.id === sectionId);
  if (!target) return;
  const existing = new Set(target.terms.map((item) => item.name));
  items.forEach((item) => {
    if (existing.has(item.name)) return;
    target.terms.push(item);
    existing.add(item.name);
  });
});

