curriculumExpansionPacksRound2.forEach((pack) => {
  const target = dictionary.find((section) => section.id === pack.target);
  if (!target) return;
  const existing = new Set(target.terms.map((item) => item.name));
  const names = pack.concepts.filter((name) => !existing.has(name));
  target.terms.push(...names.map((_, index) => systemStudyTerm(pack, names, index)));
});

function preciseStudyTerm(pack, concepts, index) {
  const name = concepts[index];
  const prev = concepts[index - 1];
  const next = concepts[index + 1];
  const tag = pack.tags[index % pack.tags.length];
  const angle = pack.angles[index % pack.angles.length];
  return term(
    name,
    tag,
    `${name}是${pack.title}里的重要术语，主要用于${pack.focus}。理解它时要把它放在${angle}中观察：先看它处理的对象，再看它依赖的前提、性能或安全边界，以及在工程里怎样被验证。`,
    `${name}像${pack.metaphor}的一枚精确零件，单独看只是一个名词，放到流程里就能解释为什么系统会更快、更稳或更容易维护。`,
    [prev, next].filter(Boolean)
  );
}

