curriculumExpansionPacksRound3.forEach((pack) => {
  const target = dictionary.find((section) => section.id === pack.target);
  if (!target) return;
  const existing = new Set(target.terms.map((item) => item.name));
  const names = pack.concepts.filter((name) => !existing.has(name));
  target.terms.push(...names.map((_, index) => preciseStudyTerm(pack, names, index)));
});

const lowValueGeneratedPattern = /(核心概念|工作机制|组成结构|关键流程|常见指标|设计权衡|错误模式|排障方法|安全边界|实践场景)$/;

const globalTermNames = new Set();
dictionary.forEach((section) => {
  section.terms = section.terms.filter((item) => {
    const name = String(item.name || "").trim();
    if (!name || globalTermNames.has(name) || lowValueGeneratedPattern.test(name)) return false;
    globalTermNames.add(name);
    return true;
  });
});

dictionary.forEach((section) => {
  section.terms.forEach((item) => {
    item.related = (item.related || []).filter((name) => globalTermNames.has(name) && name !== item.name);
  });
});

