function inferEnglishName(name) {
  const clean = String(name || "").trim();
  if (!clean) return "Computer Science Term";
  if (englishOverrides[clean]) return englishOverrides[clean];
  const phrase = englishPhraseRules.find(([zh]) => clean.includes(zh));
  if (phrase) return phrase[1];
  if (/^[A-Za-z0-9+\-./#_ ()]+$/.test(clean)) return clean;

  const suffix = englishSuffixRules.find(([zh]) => clean.endsWith(zh));
  if (suffix) {
    const prefix = clean.slice(0, -suffix[0].length).trim();
    const prefixEnglish = inferEnglishPrefix(prefix);
    return prefixEnglish ? `${prefixEnglish} ${suffix[1]}` : suffix[1];
  }

  const prefixEnglish = inferEnglishPrefix(clean);
  return prefixEnglish || `Computer Science Term: ${clean}`;
}

function inferEnglishPrefix(value) {
  const clean = String(value || "").trim();
  if (!clean) return "";
  if (englishOverrides[clean]) return englishOverrides[clean];
  if (/^[A-Za-z0-9+\-./#_ ()]+$/.test(clean)) return clean;
  const tokens = englishKeywordRules
    .filter(([zh]) => clean.includes(zh))
    .sort((a, b) => clean.indexOf(a[0]) - clean.indexOf(b[0]))
    .map(([, en]) => en);
  return [...new Set(tokens)].join(" ");
}

