function escapeHtml(value) {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function getActiveSection() {
  return dictionary.find((section) => section.id === state.activeSection) || dictionary[0];
}

function openSidebar() {
  document.body.classList.add("sidebar-open");
  mobileMenuToggle?.setAttribute("aria-expanded", "true");
  if (sidebarBackdrop) sidebarBackdrop.hidden = false;
}

function closeSidebar() {
  document.body.classList.remove("sidebar-open");
  mobileMenuToggle?.setAttribute("aria-expanded", "false");
  if (sidebarBackdrop) sidebarBackdrop.hidden = true;
}

function performSearch() {
  state.query = searchInput.value.trim();
  state.highlighted = "";
  render();
  closeSidebar();
  requestAnimationFrame(() => {
    const firstResult = document.querySelector(".term-card");
    const target = firstResult || document.querySelector(".section-head");
    target?.scrollIntoView({ behavior: "smooth", block: "start" });
  });
}

function formatDateTime(value) {
  if (!value) return "暂无时间";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return new Intl.DateTimeFormat("zh-CN", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit"
  }).format(date);
}

function renderNav() {
  nav.innerHTML = dictionary
    .map((section) => {
      const active = section.id === state.activeSection && !state.query ? " active" : "";
      const count = section.news ? "动态" : section.terms.length;
      return `
        <button class="section-button${active}" type="button" data-section="${section.id}">
          <span>${escapeHtml(section.title)}</span>
          <small>${count}</small>
        </button>
      `;
    })
    .join("");
}

function renderCategories(activeCategoryId = "") {
  categoryGrid.innerHTML = categories
    .map((category) => {
      const active = category.id === activeCategoryId ? " active" : "";
      return `<button class="${active}" type="button" data-category="${category.id}">${escapeHtml(category.title)}</button>`;
    })
    .join("");

  if (!activeCategoryId) {
    categoryPanel.classList.remove("active");
    categoryPanel.innerHTML = "";
    return;
  }

  const category = categories.find((item) => item.id === activeCategoryId);
  if (!category) return;
  const sectionButtons = category.sections
    .map((sectionId) => dictionary.find((section) => section.id === sectionId))
    .filter(Boolean)
    .map((section) => `<button type="button" data-section-jump="${section.id}">${escapeHtml(section.title)}</button>`)
    .join("");

  categoryPanel.classList.add("active");
  categoryPanel.innerHTML = `
    <h2>${escapeHtml(category.title)}</h2>
    <p>${escapeHtml(category.intro)}</p>
    <div class="category-links">${sectionButtons}</div>
  `;
}

function renderTerms() {
  const query = state.query.trim().toLowerCase();
  const active = getActiveSection();
  termsRoot.classList.toggle("news-view", !query && !!active.news);

  if (!query && active.news) {
    renderFrontierNews(active);
    return;
  }

  const list = query
    ? allTerms.filter((item) => {
        const haystack = `${item.name} ${item.english} ${item.tag} ${item.explanation} ${item.image} ${item.related.join(" ")} ${item.sectionTitle}`.toLowerCase();
        return haystack.includes(query);
      })
    : active.terms.map((item, index) => ({ ...item, sectionId: active.id, sectionTitle: active.title, order: index + 1 }));

  if (query) {
    sectionKicker.textContent = "Search";
    sectionTitle.textContent = `搜索结果：${state.query}`;
    sectionIntro.textContent = `找到 ${list.length} 个相关词条。清空搜索框可回到当前板块。`;
  } else {
    sectionKicker.textContent = active.kicker;
    sectionTitle.textContent = active.title;
    sectionIntro.textContent = active.intro;
  }

  if (!list.length) {
    termsRoot.innerHTML = `<div class="empty">没有找到匹配词条。可以换个关键词，例如“缓存”“模型”“HTTP”“事务”。</div>`;
    return;
  }

  termsRoot.innerHTML = list
    .map((item, index) => {
      const shouldOpen = query || index < 3;
      const highlight = state.highlighted === item.name ? " highlight" : "";
      return `
        <article id="${termId(item.sectionId, item.name)}" class="term-card${shouldOpen ? " open" : ""}${highlight}" data-term="${escapeHtml(item.name)}" data-section="${escapeHtml(item.sectionId)}">
          <button class="term-toggle" type="button" aria-expanded="${shouldOpen ? "true" : "false"}">
            <span class="term-index">${String(item.order || index + 1).padStart(2, "0")}</span>
            <span>
              <span class="term-title">${escapeHtml(item.name)}</span>
              <span class="term-english">${escapeHtml(item.english || inferEnglishName(item.name))}</span>
              <span class="term-tag">${escapeHtml(item.sectionTitle)} · ${escapeHtml(item.tag)}</span>
            </span>
            <span class="chevron" aria-hidden="true">›</span>
          </button>
          <div class="term-body">
            <p><strong>解释：</strong>${escapeHtml(item.explanation)}</p>
            <p><strong>形象描述：</strong>${escapeHtml(item.image)}</p>
            ${item.related.length ? `<div class="relations">${item.related.map((name) => `<span>${escapeHtml(name)}</span>`).join("")}</div>` : ""}
            <button class="detail-button" type="button" data-detail-term="${escapeHtml(item.name)}" data-detail-section="${escapeHtml(item.sectionId)}">打开详情窗口</button>
          </div>
        </article>
      `;
    })
    .join("");
}

function renderFrontierNews(section) {
  sectionKicker.textContent = section.kicker;
  sectionTitle.textContent = section.title;
  sectionIntro.textContent = section.intro;

  const newsKey = section.newsKey || "frontierNews";
  const newsState = state[newsKey] || state.frontierNews;
  const { updatedAt, nextUpdate, items, sources, errors } = newsState;
  state.activeNewsItems = items;
  const statusText = state.newsLoaded
    ? `最近更新：${formatDateTime(updatedAt)}；下次计划更新：${formatDateTime(nextUpdate)}`
    : "正在读取本地新闻数据...";

  if (!state.newsLoaded) {
    termsRoot.innerHTML = `<div class="empty">正在加载前沿科技动态。</div>`;
    return;
  }

  if (!items.length) {
    termsRoot.innerHTML = `
      <div class="empty">
        暂无新闻数据。请运行新闻更新脚本，或使用桌面熊猫图标启动后等待自动更新。
      </div>
    `;
    return;
  }

  termsRoot.innerHTML = `
    <div class="news-status">
      <div>
        <strong>${escapeHtml(statusText)}</strong>
        <p>本板块读取公开 RSS/网页摘要源，去重后按发布时间排序。摘要会尽量压缩为核心变化、影响对象和需要关注的原因。</p>
      </div>
      <div class="source-count">${items.length} 条</div>
    </div>
    <div class="news-grid">
      ${items
        .map(
          (item, index) => `
            <article class="news-card${index === 0 ? " lead" : ""}" data-news-card="${index}">
              <div class="news-meta">
                <span class="news-region">${escapeHtml(item.region || "全球")}</span>
                <span>${escapeHtml(item.source || "未知来源")}</span>
                ${item.isTranslated ? "<span>中文阅读</span>" : ""}
                <time>${escapeHtml(formatDateTime(item.publishedAt))}</time>
              </div>
              <h3><button class="news-title-button" type="button" data-news-index="${index}">${escapeHtml(item.titleZh || item.title)}</button></h3>
              <p class="news-deck">${escapeHtml(item.summary || "暂无摘要")}</p>
              <div class="news-footer">
                <div class="relations">
                  ${(item.tags || []).slice(0, 4).map((tag) => `<span>${escapeHtml(tag)}</span>`).join("")}
                </div>
                <button class="news-read-button" type="button" data-news-index="${index}">打开阅读</button>
              </div>
            </article>
          `
        )
        .join("")}
    </div>
    <div class="news-sources">
      <strong>新闻源</strong>
      <p>${sources.map((source) => escapeHtml(source.name)).join("、") || "暂无"}</p>
    </div>
  `;
}

function termId(sectionId, name) {
  return `term-${encodeURIComponent(sectionId).replace(/%/g, "")}-${encodeURIComponent(name).replace(/%/g, "")}`;
}

function renderGraph() {
  if (!graphRoot) return;
  if (state.query.trim()) {
    graphHint.textContent = "搜索模式下会跨板块显示词条；请选择某个板块查看该板块内部的联系图。";
    graphRoot.innerHTML = `<div class="empty">当前为搜索结果视图。清空搜索后可查看板块关系图。</div>`;
    return;
  }

  const active = getActiveSection();
  if (active.news) {
    graphHint.textContent = "前沿动态板块的联系图展示重点技术主题之间的影响链路。";
    graphRoot.innerHTML = `
      <svg viewBox="0 0 960 520" preserveAspectRatio="xMidYMin meet">
        <defs>
          <marker id="arrow-news" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
            <path d="M 0 0 L 10 5 L 0 10 z" fill="#8fa1a9"></path>
          </marker>
        </defs>
        <path class="edge" d="M 210 130 C 330 80, 420 80, 540 130" marker-end="url(#arrow-news)" />
        <path class="edge" d="M 210 260 C 330 260, 420 260, 540 260" marker-end="url(#arrow-news)" />
        <path class="edge" d="M 210 390 C 330 440, 420 440, 540 390" marker-end="url(#arrow-news)" />
        <path class="edge" d="M 690 130 C 760 170, 760 220, 690 260" marker-end="url(#arrow-news)" />
        <path class="edge" d="M 690 260 C 760 300, 760 350, 690 390" marker-end="url(#arrow-news)" />
        ${newsNode("AI 模型", 58, 109)}
        ${newsNode("芯片算力", 58, 239)}
        ${newsNode("网络安全", 58, 369)}
        ${newsNode("产品落地", 540, 109)}
        ${newsNode("云与开源", 540, 239)}
        ${newsNode("产业政策", 540, 369)}
      </svg>
    `;
    return;
  }

  graphHint.textContent = "关系图改为学习主线图：只展示从基础到扩展的路径，点击节点会打开词条详情窗口。";
  const section = active;
  const terms = section.terms;
  const width = 960;
  const rowGap = 92;
  const colGap = 220;
  const cols = 4;
  const rows = Math.ceil(terms.length / cols);
  const height = Math.max(430, rows * rowGap + 84);
  const nodeWidth = 168;
  const nodeHeight = 46;
  const positions = new Map();

  terms.forEach((item, index) => {
    const row = Math.floor(index / cols);
    const col = index % cols;
    const x = 44 + col * colGap;
    const y = 46 + row * rowGap;
    positions.set(item.name, { x, y });
  });

  const edges = [];

  terms.forEach((item, index) => {
    if (index < terms.length - 1) edges.push({ from: item.name, to: terms[index + 1].name });
  });

  const edgeMarkup = edges
    .map(({ from, to }) => {
      const a = positions.get(from);
      const b = positions.get(to);
      if (!a || !b) return "";
      const startX = a.x + nodeWidth;
      const startY = a.y + nodeHeight / 2;
      const endX = b.x;
      const endY = b.y + nodeHeight / 2;
      if (Math.abs(startY - endY) < 4) {
        return `<path class="edge path-edge" d="M ${startX} ${startY} L ${endX - 10} ${endY}" marker-end="url(#arrow)" />`;
      }
      const turnX = width - 54;
      return `<path class="edge path-edge" d="M ${startX} ${startY} L ${turnX} ${startY} L ${turnX} ${endY} L ${endX - 10} ${endY}" marker-end="url(#arrow)" />`;
    })
    .join("");

  const nodeMarkup = terms
    .map((item) => {
      const pos = positions.get(item.name);
      const label = item.name.length > 10 ? `${item.name.slice(0, 9)}…` : item.name;
      const activeClass = state.highlighted === item.name ? " active" : "";
      return `
        <g class="graph-node${activeClass}" tabindex="0" role="button" data-term="${escapeHtml(item.name)}" data-section="${escapeHtml(section.id)}" transform="translate(${pos.x} ${pos.y})">
          <rect width="${nodeWidth}" height="${nodeHeight}" rx="8"></rect>
          <text x="${nodeWidth / 2}" y="26" text-anchor="middle">${escapeHtml(label)}</text>
        </g>
      `;
    })
    .join("");

  graphRoot.innerHTML = `
    <svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMin meet">
      <defs>
        <marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
          <path d="M 0 0 L 10 5 L 0 10 z" fill="#8fa1a9"></path>
        </marker>
      </defs>
      ${edgeMarkup}
      ${nodeMarkup}
    </svg>
  `;
}

function newsNode(label, x, y) {
  return `
    <g class="graph-node" transform="translate(${x} ${y})">
      <rect width="152" height="42" rx="8"></rect>
      <text x="76" y="26" text-anchor="middle">${label}</text>
    </g>
  `;
}

function findTermByName(name, sectionId = "") {
  return allTerms.find((item) => item.name === name && (!sectionId || item.sectionId === sectionId));
}

function buildDeepSeekPrompt(item) {
  const related = item.related.length ? item.related.join("、") : "暂无";
  return `请用中文详细解释计算机词典词条「${item.name}（${item.english || inferEnglishName(item.name)}）」。请按以下结构回答：
1. 一句话定义
2. 初学者能懂的解释
3. 生动类比
4. 它和这些相关概念的关系：${related}
5. 常见误区
6. 一个真实工程场景
7. 继续学习路径

我的当前词典解释是：${item.explanation}
形象描述是：${item.image}`;
}

async function copyText(value) {
  if (navigator.clipboard && window.isSecureContext) {
    await navigator.clipboard.writeText(value);
    return;
  }
  const textarea = document.createElement("textarea");
  textarea.value = value;
  textarea.setAttribute("readonly", "");
  textarea.style.position = "fixed";
  textarea.style.left = "-9999px";
  document.body.appendChild(textarea);
  textarea.select();
  document.execCommand("copy");
  textarea.remove();
}

function openTermModal(name, sectionId = "") {
  const item = findTermByName(name, sectionId);
  if (!item) return;
  activeModalTerm = item;
  modalSection.textContent = item.sectionTitle;
  modalTitle.textContent = item.name;
  modalTag.textContent = `${item.english || inferEnglishName(item.name)} · ${item.tag}`;
  modalExplanation.textContent = item.explanation;
  modalImage.textContent = item.image;
  modalRelations.innerHTML = item.related.length
    ? item.related.map((related) => `<span>${escapeHtml(related)}</span>`).join("")
    : "<span>暂无相关概念</span>";
  modalNotice.textContent = "DeepSeek 按钮会先复制一段专属提问，再打开官方聊天入口。";
  termModal.hidden = false;
  document.body.classList.add("modal-open");
  copyDeepSeekPrompt.focus();
}

function closeTermModal() {
  termModal.hidden = true;
  activeModalTerm = null;
  document.body.classList.remove("modal-open");
}

function openNewsModal(index) {
  const item = state.activeNewsItems[Number(index)];
  if (!item) return;
  newsModalMeta.textContent = `${item.region || "全球"} · ${item.source || "未知来源"} · ${formatDateTime(item.publishedAt)}`;
  newsModalTitle.textContent = item.titleZh || item.title;
  newsModalSummary.textContent = item.summary || "暂无摘要";
  newsModalBody.textContent = item.readerTextZh || item.summary || "当前来源未提供足够正文，已保留中文摘要和原文入口。";
  newsOriginalLink.href = item.url;
  newsModal.hidden = false;
  document.body.classList.add("modal-open");
  newsOriginalLink.focus();
}

function closeNewsModal() {
  newsModal.hidden = true;
  document.body.classList.remove("modal-open");
}

function render() {
  renderNav();
  if (!categoryGrid.querySelector("button")) renderCategories();
  renderTerms();
  if (graphRoot) renderGraph();
  bindDynamicEvents();
}

function bindDynamicEvents() {
  document.querySelectorAll(".term-toggle").forEach((button) => {
    button.addEventListener("click", () => {
      const card = button.closest(".term-card");
      const open = !card.classList.contains("open");
      card.classList.toggle("open", open);
      button.setAttribute("aria-expanded", String(open));
    });
  });

  document.querySelectorAll("[data-detail-term]").forEach((button) => {
    button.addEventListener("click", () => {
      openTermModal(button.getAttribute("data-detail-term"), button.getAttribute("data-detail-section"));
    });
  });

  document.querySelectorAll("[data-news-index]").forEach((button) => {
    button.addEventListener("click", () => {
      openNewsModal(button.getAttribute("data-news-index"));
    });
  });

  document.querySelectorAll(".graph-node").forEach((node) => {
      if (!node.hasAttribute("data-term")) return;
    const focusTerm = () => {
      const name = node.getAttribute("data-term");
      const sectionId = node.getAttribute("data-section") || state.activeSection;
      state.highlighted = name;
      const card = document.getElementById(termId(sectionId, name));
      if (card) {
        card.classList.add("open", "highlight");
        card.querySelector(".term-toggle")?.setAttribute("aria-expanded", "true");
        card.scrollIntoView({ behavior: "smooth", block: "center" });
      }
      openTermModal(name, sectionId);
      renderGraph();
    };
    node.addEventListener("click", focusTerm);
    node.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        focusTerm();
      }
    });
  });
}

nav.addEventListener("click", (event) => {
  const button = event.target.closest("[data-section]");
  if (!button) return;
  state.activeSection = button.getAttribute("data-section");
  state.query = "";
  state.highlighted = "";
  searchInput.value = "";
  render();
  closeSidebar();
  document.querySelector(".section-head").scrollIntoView({ behavior: "smooth", block: "start" });
});

categoryGrid.addEventListener("click", (event) => {
  const button = event.target.closest("[data-category]");
  if (!button) return;
  renderCategories(button.getAttribute("data-category"));
  categoryPanel.scrollIntoView({ behavior: "smooth", block: "nearest" });
});

categoryPanel.addEventListener("click", (event) => {
  const button = event.target.closest("[data-section-jump]");
  if (!button) return;
  state.activeSection = button.getAttribute("data-section-jump");
  state.query = "";
  state.highlighted = "";
  searchInput.value = "";
  render();
  closeSidebar();
  document.querySelector(".section-head").scrollIntoView({ behavior: "smooth", block: "start" });
});

searchInput.addEventListener("keydown", (event) => {
  if (event.key !== "Enter") return;
  event.preventDefault();
  performSearch();
});

searchButton?.addEventListener("click", performSearch);

mobileMenuToggle?.addEventListener("click", () => {
  if (document.body.classList.contains("sidebar-open")) {
    closeSidebar();
  } else {
    openSidebar();
  }
});

mobileSearchFocus?.addEventListener("click", () => {
  openSidebar();
  requestAnimationFrame(() => searchInput.focus());
});

sidebarBackdrop?.addEventListener("click", closeSidebar);

document.querySelector("#expandAll").addEventListener("click", () => {
  if (getActiveSection().news && !state.query.trim()) {
    document.querySelectorAll(".news-card").forEach((card) => card.classList.remove("collapsed"));
    return;
  }
  document.querySelectorAll(".term-card").forEach((card) => {
    card.classList.add("open");
    card.querySelector(".term-toggle")?.setAttribute("aria-expanded", "true");
  });
});

document.querySelector("#collapseAll").addEventListener("click", () => {
  if (getActiveSection().news && !state.query.trim()) {
    document.querySelectorAll(".news-card").forEach((card) => card.classList.add("collapsed"));
    return;
  }
  document.querySelectorAll(".term-card").forEach((card) => {
    card.classList.remove("open");
    card.querySelector(".term-toggle")?.setAttribute("aria-expanded", "false");
  });
});

document.querySelectorAll("[data-close-modal]").forEach((target) => {
  target.addEventListener("click", closeTermModal);
});

document.querySelectorAll("[data-close-news]").forEach((target) => {
  target.addEventListener("click", closeNewsModal);
});

document.addEventListener("keydown", (event) => {
  if (event.key === "Escape" && !termModal.hidden) closeTermModal();
  if (event.key === "Escape" && !newsModal.hidden) closeNewsModal();
  if (event.key === "Escape" && document.body.classList.contains("sidebar-open")) closeSidebar();
});

copyDeepSeekPrompt.addEventListener("click", async () => {
  if (!activeModalTerm) return;
  await copyText(buildDeepSeekPrompt(activeModalTerm));
  modalNotice.textContent = "问题已自动复制好。DeepSeek 打开后，直接粘贴发送即可。";
  window.open("https://www.deepseek.com/chat", "_blank", "noreferrer");
});

copyTermPrompt.addEventListener("click", async () => {
  if (!activeModalTerm) return;
  await copyText(buildDeepSeekPrompt(activeModalTerm));
  modalNotice.textContent = "问题已复制。";
});

render();

function normalizeNewsPayload(payload) {
  return {
    updatedAt: payload.updatedAt || "",
    nextUpdate: payload.nextUpdate || "",
    items: Array.isArray(payload.items) ? payload.items : [],
    sources: Array.isArray(payload.sources) ? payload.sources : [],
    errors: Array.isArray(payload.errors) ? payload.errors : []
  };
}

async function fetchNewsFile(path) {
  const response = await fetch(path, { cache: "no-store" });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  return normalizeNewsPayload(await response.json());
}

async function loadNewsFeeds() {
  try {
    state.frontierNews = await fetchNewsFile("data/frontier-news.json");
  } catch (error) {
    state.frontierNews = {
      updatedAt: "",
      nextUpdate: "",
      items: [],
      sources: [],
      errors: [{ source: "本地数据文件", error: error.message }]
    };
  }

  try {
    state.wechatNews = await fetchNewsFile("data/wechat-news.json");
  } catch (error) {
    state.wechatNews = {
      updatedAt: "",
      nextUpdate: "",
      items: [],
      sources: [],
      errors: [{ source: "公众号数据文件", error: error.message }]
    };
  } finally {
    state.newsLoaded = true;
    if (getActiveSection().news) render();
  }
}

loadNewsFeeds();
